     m_dragImages.insert(row, dragImage);
 }

+void FolderModel::grabItemDragImage(QQuickItem *item, int row, const QRectF &rect, const QJSValue &callback)
+{
+    // Unlike the QML grabToImage(), the result isn't owned by the item, so the render thread
+    // can't use it after the item was deleted (e.g. when the view changes folders mid-grab).
+    QSharedPointer<QQuickItemGrabResult> result = item->grabToImage();
+    if (!result) {
+        return;
+    }
+
+    connect(
+        result.data(),
+        &QQuickItemGrabResult::ready,
+        this,
+        [this, result, item = QPointer(item), row, rect, callback]() mutable {
+            if (item) {
+                const QRect itemRect = rect.toRect();
+                addItemDragImage(row, itemRect.x(), itemRect.y(), itemRect.width(), itemRect.height(), result->image());
+                callback.call();
+            }
+            // Release the result only after it has finished emitting.
+            QMetaObject::invokeMethod(this, [result = std::move(result)] { }, Qt::QueuedConnection);
+        },
+        Qt::SingleShotConnection);
+}
+
 void FolderModel::clearDragImages()
 {
     qDeleteAll(m_dragImages);
@@ -1787,6 +1829,23 @@ inline bool FolderModel::matchPattern(const KFileItem &item) const
     return false;
 }

+bool FolderModel::matchFilterText(const KFileItem &item) const
+{
+    if (m_filterText.isEmpty()) {
+        return true;
+    }
+
+    QString name = item.name();
+    if (item.isDesktopFile()) {
+        const QString desktopName = KDesktopFile(item.localPath()).readName();
+        if (!desktopName.isEmpty()) {
+            name = desktopName;
+        }
+    }
+
+    return name.contains(m_filterText, Qt::CaseInsensitive);
+}
